CREATE DATABASE IF NOT EXISTS enlazate CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE enlazate;

CREATE TABLE admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(120) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, last_login_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, business_name VARCHAR(190) NOT NULL, contact_name VARCHAR(120) NOT NULL, phone VARCHAR(40) NOT NULL, email VARCHAR(190) NULL, rnc VARCHAR(30) NULL, address VARCHAR(255) NULL, city VARCHAR(100) NULL, province VARCHAR(100) NULL, notes TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, INDEX idx_customers_business (business_name));
CREATE TABLE product_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(140) NOT NULL UNIQUE, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NULL, name VARCHAR(190) NOT NULL, slug VARCHAR(210) NOT NULL UNIQUE, description TEXT NULL, price_dop DECIMAL(12,2) NOT NULL DEFAULT 0, production_cost_dop DECIMAL(12,2) NULL, lead_time_days SMALLINT UNSIGNED NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, FOREIGN KEY (category_id) REFERENCES product_categories(id) ON DELETE SET NULL);
CREATE TABLE qr_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(12) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NULL, product_id BIGINT UNSIGNED NULL, label VARCHAR(190) NOT NULL, type ENUM('url','menu','reviews','whatsapp','wifi','maps','contact','nfc') NOT NULL DEFAULT 'url', status ENUM('active','paused','expired','archived') NOT NULL DEFAULT 'active', expires_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL, FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL, INDEX idx_qr_status (status));
CREATE TABLE qr_destinations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, qr_code_id BIGINT UNSIGNED NOT NULL, destination_url VARCHAR(2048) NOT NULL, is_current TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (qr_code_id) REFERENCES qr_codes(id) ON DELETE CASCADE, INDEX idx_destination_current (qr_code_id,is_current));
CREATE TABLE qr_destination_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, qr_code_id BIGINT UNSIGNED NOT NULL, destination_url VARCHAR(2048) NOT NULL, changed_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (qr_code_id) REFERENCES qr_codes(id) ON DELETE CASCADE, FOREIGN KEY (changed_by) REFERENCES admins(id) ON DELETE SET NULL);
CREATE TABLE qr_scans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, qr_code_id BIGINT UNSIGNED NOT NULL, scanned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, device_type VARCHAR(40) NULL, browser VARCHAR(100) NULL, country_code CHAR(2) NULL, ip_hash CHAR(64) NULL, FOREIGN KEY (qr_code_id) REFERENCES qr_codes(id) ON DELETE CASCADE, INDEX idx_scans_qr_date (qr_code_id,scanned_at));
CREATE TABLE settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NOT NULL, is_secret TINYINT(1) NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, admin_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, metadata JSON NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE SET NULL, INDEX idx_audit_date (created_at));
INSERT INTO settings (setting_key,setting_value) VALUES ('brand_name','ENLÁZATE'),('tagline','Tu negocio, más conectado.'),('currency','DOP'),('timezone','America/Santo_Domingo'),('qr_base_url','https://enlazate.com.do/r') ON DUPLICATE KEY UPDATE setting_key=setting_key;
INSERT INTO product_categories (name,slug) VALUES ('Enlázate Menú','menu'),('Enlázate Opiniones','opiniones'),('Enlázate Contacto','contacto'),('Enlázate Wi-Fi','wifi'),('Enlázate NFC','nfc'),('Enlázate Señaliza','senaliza') ON DUPLICATE KEY UPDATE name=VALUES(name);
